{{ config(
            materialized='table',
                post_hook={
                    "sql": "Create or Replace table maplemonk.zouk_inwards_actual_vs_target_MTD as WITH TARGETS AS ( WITH parsed_dates AS ( SELECT PARSE_DATE(\'%d-%b-%y\', Start_Date) AS Start_Date, PARSE_DATE(\'%d-%b-%y\', End_Date) AS End_Date, CAST(REPLACE(Target,\',\',\'\') AS FLOAT64) AS Target, POC, UPPER(Vendor) AS Vendor, UPPER(Category) AS Category FROM maplemonk.inward_target ), date_series AS ( SELECT Start_Date, End_Date, Target, POC, Vendor, Category, DATE_ADD(Start_Date, INTERVAL day_offset DAY) AS daily_date FROM parsed_dates, UNNEST(GENERATE_ARRAY(0, DATE_DIFF(End_Date, Start_Date, DAY))) AS day_offset ) SELECT daily_date AS Date, Target / (DATE_DIFF(End_Date, Start_Date, DAY) + 1) AS Daily_Target, POC, Vendor, Category, ROW_NUMBER() OVER (PARTITION BY daily_date, Vendor, Category ORDER BY daily_date) AS rn FROM date_series ), category_to_collection AS ( SELECT UPPER(Category) AS Category, Collection, Product_Type FROM ( SELECT UPPER(Category) AS Category, Collection, Product_Type, ROW_NUMBER() OVER (PARTITION BY UPPER(Category) ORDER BY Collection) AS rn FROM `zouk-wh.maplemonk.final_sku_master` WHERE Category IS NOT NULL AND Collection IS NOT NULL ) WHERE rn = 1 ), inwards_base AS ( SELECT SAFE.PARSE_DATE(\'%m/%d/%Y\', fi.Date) AS Date, UPPER(fi.Vendor) AS Vendor, UPPER(pid.Category) AS Category, UPPER(pid.Collection) AS Collection, UPPER(pid.Product_Type), SUM(SAFE_CAST(fi.Inward_Quantity AS INT64)) AS Inward_Quantity FROM maplemonk.inward_data fi LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY commonsku ORDER BY commonsku) AS rw FROM `zouk-wh.maplemonk.final_sku_master` ) WHERE rw = 1 ) pid ON LOWER(fi.sku_id) = LOWER(pid.commonsku) WHERE fi.Date IS NOT NULL AND fi.Date != \'#REF!\' GROUP BY 1, 2, 3,4,5 ), inwards AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY Date, Vendor, Category ORDER BY Date) AS rn FROM inwards_base ), Combined AS ( SELECT COALESCE(inw.Date, tar.Date) AS Date, UPPER(COALESCE(inw.Vendor, tar.Vendor)) AS Vendor, UPPER(COALESCE(inw.Category, tar.Category)) AS Category, tar.POC, IFNULL(inw.Inward_Quantity, 0) AS Inward_Quantity, IFNULL(tar.Daily_Target, 0) AS targets, ROW_NUMBER() OVER (PARTITION BY COALESCE(inw.Date, tar.Date), COALESCE(inw.Vendor, tar.Vendor), COALESCE(inw.Category, tar.Category) ORDER BY COALESCE(inw.Date, tar.Date)) AS row_check FROM inwards inw FULL OUTER JOIN TARGETS tar ON LOWER(inw.Category) = LOWER(tar.Category) AND CAST(inw.Date AS DATE) = CAST(tar.Date AS DATE) AND LOWER(inw.Vendor) = LOWER(tar.Vendor) AND inw.rn = tar.rn ) SELECT t.*, col.Collection, col.Product_Type FROM Combined t LEFT JOIN category_to_collection col ON t.Category = col.Category ; Create or Replace table maplemonk.Zouk_Vendor_Supply_vs_capacity as WITH TARGETS as( WITH parsed_dates AS ( SELECT PARSE_DATE(\'%d-%b-%y\', Start_Date) AS Start_Date, PARSE_DATE(\'%d-%b-%y\', End_Date) AS End_Date, CAST(REPLACE(Target,\',\',\'\') AS FLOAT64) AS Target, POC, Upper(Vendor) as Vendor, Upper(Category) as Category FROM `MapleMonk.Zouk_Production_Capacity` ), date_series AS ( SELECT Start_Date, End_Date, Target, POC, Vendor, Category, DATE_ADD(Start_Date, INTERVAL day_offset DAY) AS daily_date FROM parsed_dates, UNNEST(GENERATE_ARRAY(0, DATE_DIFF(End_Date, Start_Date, DAY))) AS day_offset ) SELECT daily_date AS Date, Target / (DATE_DIFF(End_Date, Start_Date, DAY) + 1) AS Daily_Target, POC, Vendor, Category FROM date_series ORDER BY Date ), inwards as ( select SAFE.PARSE_DATE(\'%m/%d/%Y\', Date) Date, Upper(vendor) As Vendor, Upper(category) as Category, sum(safe_cast(Inward_Quantity as int64)) as Inward_Quantity, from maplemonk.inward_data fi left join (select * from (select marketplace_sku skucode, name, category, sub_category, category_code, collection, print, PRODUCT_TYPE, commonsku, BAU_OFFLINE, BAU_ONLINE, TAX_RATE , row_number() over (partition by commonsku order by 1) rw from zouk-wh.maplemonk.final_sku_master ) where rw = 1 )pid on lower(fi.sku_id) = lower(pid.commonsku) where date is not null and date != \'#REF!\' group by 1,2,3 ) Select coalesce(inw.date,tar.date) as date, Upper(coalesce(inw.vendor,tar.vendor)) as vendor, Upper(coalesce(inw.category,tar.category)) as category, tar.poc, ifnull(inw.Inward_Quantity,0) Inward_Quantity, ifnull(tar.Daily_Target,0) targets from inwards inw full outer join TARGETS tar on lower(inw.Category) = lower(tar.Category) and cast(inw.Date as date) = cast(tar.date as date) and lower(inw.Vendor) = lower(tar.Vendor) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
